        for di, dj in dirs:
            x, y = i + di, j + dj
            if 0 <= x < n and 0 <= y < m and g[x][y] == '.':
                c += 1
        return c

    def ok(i, j):
        # Only cell (i,j) and its marked neighbours have changed counts.
        cells = [(i, j)]
        for di, dj in dirs:
            x, y = i + di, j + dj
            if 0 <= x < n and 0 <= y < m and g[x][y] == 'X':
