                lo, hi = 1, N
            u = rng.randint(lo, hi)
            v = rng.randint(lo, hi - 1 if hi > lo else hi)
            if v >= u:
                v += 1
            if hi == lo:
                v = u % N + 1
            edges.append((u, v))
    elif kind == 'mid':
        N = 25000
        M = 6200
        edges = []
        for _ in range(M):
            if rng.random() < 0.5:
                lo, hi = 1, min(N, 200)
            else:
                lo, hi = 1, N
            u = rng.randint(lo, hi)
            v = rng.randint(lo, hi - 1)
            if v >= u:
                v += 1
            edges.append((u, v))
    elif kind == 'edge':
        choice = rng.randrange(3)
        if choice == 0:
            N, M = 2, 1
            edges = [(1, 2)]
