import sys
import random


def build(n, k, rng):
    vals = []
    p_neg = rng.random() * 0.6
    for _ in range(n):
        if rng.random() < p_neg:
            vals.append(-1)
        else:
            vals.append(rng.randrange(k))
    return f"{n} {k}\n" + " ".join(map(str, vals)) + "\n"


def main():
    seed = int(sys.argv[1])
    kind = sys.argv[2]
    rng = random.Random(seed)
    MAXN = 100000
    MAXK = 10**9
    LIMIT = 899000

    if kind == "max":
        k = rng.randint(2, MAXK)
        n = MAXN
        s = build(n, k, rng)
        # Keep output under the byte limit by trimming n if values are long.
        while len(s) > LIMIT and n > 2:
            n -= 1000
            if n < 2:
                n = 2
            s = build(n, k, rng)
            if n == 2:
                break
        sys.stdout.write(s)

    elif kind == "mid":
        n = rng.randint(8000, 12000)
        k = rng.randint(2, MAXK // 10)
        sys.stdout.write(build(n, k, rng))

    elif kind == "edge":
        choice = rng.randrange(4)
        if choice == 0:
            sys.stdout.write("2 2\n-1 -1\n")
        elif choice == 1:
            sys.stdout.write(f"2 {MAXK}\n0 {MAXK - 1}\n")
        elif choice == 2:
            sys.stdout.write(f"2 {MAXK}\n-1 -1\n")
        else:
            n = MAXN
            vals = " ".join(["-1"] * n)
            sys.stdout.write(f"{n} 2\n{vals}\n")
    else:
        raise SystemExit("KIND must be max, mid, or edge")


if __name__ == "__main__":
    main()
