import sys
import random


def make_step(rng, n, q):
    idx = sorted(rng.sample(range(1, n + 1), q))
    return str(q) + " " + " ".join(map(str, idx))


def main():
    seed = int(sys.argv[1])
    kind = sys.argv[2]
    rng = random.Random(seed)

    if kind == "max":
        n = 40
        k = 10
        steps = []
        for _ in range(k):
            # Mix of arbitrary sizes and sizes near the maximum.
            if rng.random() < 0.5:
                q = rng.randint(1, n)
            else:
                q = rng.randint(max(1, n - 3), n)
            steps.append(make_step(rng, n, q))
    elif kind == "mid":
        n = 4
        k = 1
        steps = []
        for _ in range(k):
            q = rng.randint(1, n)
            steps.append(make_step(rng, n, q))
    elif kind == "edge":
        n = rng.choice([1, 40])
        k = rng.choice([0, 10])
        steps = []
        for _ in range(k):
            # Degenerate structure: singleton or full-array steps.
            if rng.random() < 0.5:
                q = 1
            else:
                q = n
            steps.append(make_step(rng, n, q))
    else:
        raise SystemExit("KIND must be one of: max, mid, edge")

    out = [f"{n} {k}"] + steps
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
