import sys
import random


def build(seed, kind, scale=1.0):
    rng = random.Random(seed)

    if kind == 'edge':
        n = rng.choice([2, 3, 4, 5])
        maxm = n * (n - 1) // 2
        m = rng.randint(n - 1, maxm)
        q = rng.choice([0, 1, 3])

        def wf():
            return rng.choice([1, 10**9])

        def df():
            return rng.choice([1, 10**9])

        def xf():
            return rng.choice([1, 4 * 10**8])
    else:
        if kind == 'max':
            base = (14000, 21000, 14000)
        else:  # mid
            base = (1400, 2100, 1400)
        n, m, q = [max(1, int(b * scale)) for b in base]

        def wf():
            return rng.randint(1, 10**9)

        def df():
            return rng.randint(1, 10**9)

        def xf():
            return rng.randint(1, 4 * 10**8)

    m = max(n - 1, min(m, n * (n - 1) // 2))

    # Random spanning tree guarantees connectivity.
    E = set()
    el = []
    for i in range(2, n + 1):
        p = rng.randint(1, i - 1)
        E.add((p, i))
        el.append((p, i))

    # Extra distinct edges up to m (no self-loops, no multi-edges).
    while len(el) < m:
        u = rng.randint(1, n)
        v = rng.randint(1, n)
        if u == v:
            continue
        a, b = min(u, v), max(u, v)
        if (a, b) in E:
            continue
        E.add((a, b))
        el.append((a, b))

    lines = [f"{n} {m} {q}", ' '.join(str(wf()) for _ in range(n))]
    for a, b in el:
        if rng.random() < 0.5:
            a, b = b, a
        lines.append(f"{a} {b} {df()}")
    for _ in range(q):
        lines.append(f"{rng.randint(1, n)} {xf()}")
    return '\n'.join(lines) + '\n'


def main():
    seed = int(sys.argv[1])
    kind = sys.argv[2]
    scale = 1.0
    while True:
        out = build(seed, kind, scale)
        if kind == 'edge' or len(out.encode()) <= 890000:
            break
        scale *= 0.9
    sys.stdout.write(out)


if __name__ == '__main__':
    main()
